using NUnit.Framework;
using NSpec;

public class calculator_spec : nspec
{
    Calculator calc = null;

    void before_each()
    {
        calc = new Calculator();
    }

    void adding_two_numbers()
    {
        // act
        int result = calc.Add(2, 3);

        // assert
        it["should return the sum"] = () => result.should_be(5);
        it["should not be zero"] = () => result.should_not_be(0);
    }
}

// Helper
extensions.should_be = (int actual, int expected) => Assert.AreEqual(expected, actual);
extensions.should_not_be = (int actual, int expected) => Assert.AreNotEqual(expected, actual);
